means=np.array([-.1]+[.5]*9+[5.]*10); scales=np.array([8.2/np.sqrt(12)]+[.5]*9+[10/np.sqrt(12)]*10)
widths=np.array([4.1]+[.5]*9+[5.]*10)
Z=(X-means)/scales
cont=[0]+list(range(10,20))
Q=np.zeros_like(X)
for j in cont: Q[:,j]=np.sqrt(12)*(np.abs((X[:,j]-means[j])/widths[j])-.5)
cols=[np.ones(n+nv)]+[Z[:,i] for i in range(20)]
meta=[('intercept',)]+[('linear',i) for i in range(20)]
for j in cont:
 for knot in ([ -2.05-.1, -.1, 2.05-.1] if j==0 else [2.5,5,7.5]):
  cols.append(np.maximum(X[:,j]-knot,0)/scales[j]); meta.append(('hinge',j,knot))
main_count=len(cols)
for i in range(20):
 for j in range(i+1,20):
  cols.append(Z[:,i]*Z[:,j]); meta.append(('interaction',i,j))
lin_end=len(cols)
for j in cont:
 for i in range(20):
  if i!=j:
   cols.append(Q[:,j]*Z[:,i]); meta.append(('qlinear',j,i))
q_end=len(cols)
for a1,i in enumerate(cont):
 for j in cont[a1+1:]:
  cols.append(Q[:,i]*Q[:,j]); meta.append(('qq',i,j))
F=np.column_stack(cols); a=F[:n].T@F[:n]; rhs=F[:n].T@y[:n]
b=np.linalg.solve(a+np.eye(F.shape[1])*.0001,rhs)
r=y[n:]-F[n:]@b

raw_order=sorted(range(main_count,lin_end),key=lambda k:-abs(b[k]))
q_order=sorted(range(lin_end,q_end),key=lambda k:-abs(b[k]))
qq_order=sorted(range(q_end,len(meta)),key=lambda k:-abs(b[k]))
M=X[n:].copy();M[:,10:]=5
zm=(M-means)/scales; qm=np.zeros_like(M)
for j in cont:qm[:,j]=np.sqrt(12)*(np.abs((M[:,j]-means[j])/widths[j])-.5)
mc=[]
for m in meta:
 if m[0]=='intercept':mc.append(np.ones(nv))
 elif m[0]=='linear':mc.append(zm[:,m[1]])
 elif m[0]=='hinge':mc.append(np.maximum(M[:,m[1]]-m[2],0)/scales[m[1]])
 elif m[0]=='interaction':mc.append(zm[:,m[1]]*zm[:,m[2]])
 elif m[0]=='qlinear':mc.append(qm[:,m[1]]*zm[:,m[2]])
 elif m[0]=='qq':mc.append(qm[:,m[1]]*qm[:,m[2]])
FM=np.column_stack(mc);ym=predict(M).ravel()
for nl,nq,nqq in [(80,60,0),(80,60,5),(80,60,10),(80,60,20),(80,60,30),(80,60,55),(100,100,10),(100,100,55)]:
 ks=list(range(main_count))+raw_order[:nl]+q_order[:nq]+qq_order[:nqq]
 bs=np.linalg.solve(a[np.ix_(ks,ks)],rhs[ks]); rs=y[n:]-F[n:,ks]@bs;rm=ym-FM[:,ks]@bs
 print(nl,nq,nqq,'valRMSE',np.sqrt(np.mean(rs*rs)),'centralrmse',np.sqrt(np.mean(rm*rm)),'centralbias',rm.mean())
